function safe(expr){
  let e=expr.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').replace(/π/g,'('+Math.PI+')').replace(/\be\b/g,'('+Math.E+')');
  const cl=e.replace(/\d+\.?\d*(?:e[+\-]?\d+)?/gi,'').replace(/[+\-*/.()]/g,'').trim();
  if(cl.length)return null;
  let o=(e.match(/\(/g)||[]).length,c=(e.match(/\)/g)||[]).length;e+=')'.repeat(Math.max(0,o-c));
  try{const r=Function('"use strict";return('+e+')')();return(typeof r==='number'&&!isNaN(r))?r:null;}catch{return null;}
}

