function updatePomDisplay(){
  const m=Math.floor(pomLeft/60),s=pomLeft%60;
  const el=document.getElementById('pomTime');if(el)el.textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
