let qr22_logoData=null;
let qr22_lastURL=null;
let qr22_history=[];
let qr22_debTimer=null;

const QR22_TEMPLATES={
  url:{label:'Website URL',placeholder:'https://example.com',prefix:''},
  upi:{label:'UPI ID or Amount',placeholder:'name@okhdfcbank or upi://pay?pa=name@upi&am=100',prefix:''},
  wifi:{label:'WiFi (SSID:Password)',placeholder:'MyWiFi:MyPassword',prefix:'WIFI:S:{val};;',isWifi:true},
  phone:{label:'Phone Number',placeholder:'+91 9876543210',prefix:'tel:'},
  email:{label:'Email Address',placeholder:'you@example.com',prefix:'mailto:'},
  text:{label:'Plain Text',placeholder:'Hello, World!',prefix:''},
  location:{label:'Google Maps URL or lat,lng',placeholder:'https://maps.google.com/?q=... or 28.6139,77.2090',prefix:''},
  apk:{label:'App Download URL',placeholder:'https://yoursite.com/app.apk',prefix:''}
};

function qr22SetTemplate(tpl){
  const cfg=QR22_TEMPLATES[tpl]||QR22_TEMPLATES.url;
  const lbl=document.getElementById('qr22InputLabel');
  const inp=document.getElementById('qr22Input');
  if(lbl)lbl.textContent=cfg.label;
  if(inp){inp.placeholder=cfg.placeholder;inp.value='';}
  document.querySelectorAll('.qr22-tpl').forEach(b=>{
    b.classList.toggle('active',b.getAttribute('data-tpl')===tpl);
  });
  window._qr22tpl=tpl;
}

function qr22Debounce(){
  clearTimeout(qr22_debTimer);
  qr22_debTimer=setTimeout(qr22Generate,700);
}

function qr22BuildText(){
  const inp=document.getElementById('qr22Input');
  if(!inp)return'';
  let val=inp.value.trim();
  if(!val)return'';
  const tpl=window._qr22tpl||'url';
  const cfg=QR22_TEMPLATES[tpl]||QR22_TEMPLATES.url;
  if(cfg.isWifi){
    const parts=val.split(':');
    const ssid=parts[0]||val;const pwd=parts.slice(1).join(':')||'';
    return`WIFI:T:WPA;S:${ssid};P:${pwd};;`;
  }
  if(cfg.prefix&&!val.startsWith(cfg.prefix)&&!val.startsWith('http')&&!val.startsWith('upi')&&!val.startsWith('mailto')&&!val.startsWith('tel'))
    return cfg.prefix+val;
  return val;
}

function qr22OverlayLogo(imgEl,size){
  /* Draw QR + logo on canvas, replace img src */
  const canvas=document.createElement('canvas');
  const s=Math.min(size,280);
  canvas.width=s;canvas.height=s;
  const ctx=canvas.getContext('2d');
  ctx.drawImage(imgEl,0,0,s,s);
  const logo=new Image();
  logo.crossOrigin='anonymous';
  logo.onload=function(){
    const ls=s*0.22;
    const lx=(s-ls)/2;const ly=(s-ls)/2;
    ctx.fillStyle='#fff';
    ctx.beginPath();ctx.roundRect(lx-4,ly-4,ls+8,ls+8,8);ctx.fill();
    ctx.drawImage(logo,lx,ly,ls,ls);
    imgEl.src=canvas.toDataURL('image/png');
    window._qr22canvasPNG=canvas.toDataURL('image/png');
  };
  logo.src=qr22_logoData;
}

function qr22Download(fmt){
  if(!qr22_lastURL){toast('⬆ Generate a QR first');return;}
  if(fmt==='svg'){
    /* Build SVG QR via qrserver */
    const text=qr22BuildText();
    const color=document.getElementById('qr22Color')?document.getElementById('qr22Color').value.replace('#',''):'000000';
    const bg=document.getElementById('qr22Bg')?document.getElementById('qr22Bg').value.replace('#',''):'ffffff';
    const svgURL=`https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(text)}&color=${color}&bgcolor=${bg}&margin=10&format=svg`;
    const a=document.createElement('a');a.href=svgURL;a.download='SuvoCalc-QR.svg';a.target='_blank';a.click();
    toast('📥 SVG downloading…');return;
  }
  /* PNG — use canvas if logo overlay was done */
  if(window._qr22canvasPNG){
    const a=document.createElement('a');a.href=window._qr22canvasPNG;a.download='SuvoCalc-QR.png';a.click();
    toast('📥 PNG downloaded!');return;
  }
  /* Direct fetch & download */
  fetch(qr22_lastURL)
    .then(r=>r.blob())
    .then(blob=>{
      const url=URL.createObjectURL(blob);
      const a=document.createElement('a');a.href=url;a.download='SuvoCalc-QR.png';a.click();
      setTimeout(()=>URL.revokeObjectURL(url),3000);
      toast('📥 PNG downloaded!');
    })
    .catch(()=>{
      /* Last resort: open in new tab */
      window.open(qr22_lastURL,'_blank');
      toast('📥 Right-click → Save image');
    });
}

function qr22CopyURL(){
  const inp=document.getElementById('qr22Input');
  const val=inp?inp.value.trim():'';
  if(!val){toast('Nothing to copy');return;}
  navigator.clipboard&&navigator.clipboard.writeText(val)
    .then(()=>toast('📋 URL copied!'))
    .catch(()=>toast('Copy failed'));
}

function qr22Share(){
  if(!qr22_lastURL){toast('Generate a QR first');return;}
  const text=qr22BuildText();
  if(navigator.share){
    navigator.share({title:'QR Code – SuvoCalc',text:'QR Code generated with SuvoCalc',url:text}).catch(()=>{});
  } else {
    navigator.clipboard&&navigator.clipboard.writeText(text)
      .then(()=>toast('📋 Link copied to share!'));
  }
}

function qr22LogoSelected(input){
  const file=input&&input.files&&input.files[0];
  if(!file)return;
  const reader=new FileReader();
  reader.onload=function(e){
    qr22_logoData=e.target.result;
    window._qr22canvasPNG=null;
    const d=document.getElementById('qr22LogoDisplay');
    if(d)d.innerHTML='✅ Logo loaded: <strong>'+file.name.slice(0,24)+'</strong> — <span style="color:var(--re);cursor:pointer" onclick="qr22ClearLogo()">Remove</span>';
    toast('🖼 Logo loaded! Regenerate QR to apply.');
  };
  reader.readAsDataURL(file);
}

function qr22ClearLogo(){
  qr22_logoData=null;window._qr22canvasPNG=null;
  const d=document.getElementById('qr22LogoDisplay');
  if(d)d.innerHTML='🖼 Tap to upload logo (PNG/JPG) — will appear in center';
  toast('Logo removed');
}

function qr22AddHistory(text,tpl,imgUrl){
  const tplEmoji={url:'🌐',upi:'💳',wifi:'📶',phone:'📞',email:'✉️',text:'📝',location:'📍',apk:'📦'};
  qr22_history.unshift({text,tpl,imgUrl,time:new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})});
  if(qr22_history.length>6)qr22_history.pop();
  qr22RenderHistory();
}

function qr22RenderHistory(){
  const sec=document.getElementById('qr22HistorySection');
  const list=document.getElementById('qr22HistList');
  if(!sec||!list||!qr22_history.length)return;
  sec.style.display='block';
  const tplEmoji={url:'🌐',upi:'💳',wifi:'📶',phone:'📞',email:'✉️',text:'📝',location:'📍',apk:'📦'};
  list.innerHTML=qr22_history.map((h,i)=>`
    <div class="qr22-hist-item" onclick="qr22RestoreHistory(${i})">
      <span class="qr22-hist-ico">${tplEmoji[h.tpl]||'▦'}</span>
      <span class="qr22-hist-txt">${h.text.length>40?h.text.slice(0,37)+'…':h.text}</span>
      <span class="qr22-hist-time">${h.time}</span>
    </div>`).join('');
}

function qr22RestoreHistory(i){
  const h=qr22_history[i];if(!h)return;
  qr22SetTemplate(h.tpl);
  const inp=document.getElementById('qr22Input');
  if(inp)inp.value=h.text;
  qr22Generate();
}

