var _qrStream = null;
var _qrInterval = null;

function stopQRScan(){
  if(_qrStream){ _qrStream.getTracks().forEach(function(t){t.stop();}); _qrStream=null; }
  if(_qrInterval){ clearInterval(_qrInterval); _qrInterval=null; }
  var video = document.getElementById('qrVideo');
  var frame = document.getElementById('qrFrame');
  if(video) video.style.display='none';
  if(frame){ frame.style.display='flex'; var sl=document.getElementById('qrScanLine'); if(sl)sl.remove(); }
}

function scanQRFile(input){
  var file = input.files[0];
  if(!file) return;
  if(window.BarcodeDetector){
    var img = new Image();
    img.onload = function(){
      var canvas = document.createElement('canvas');
      canvas.width=img.width; canvas.height=img.height;
      canvas.getContext('2d').drawImage(img,0,0);
      var detector = new BarcodeDetector({formats:['qr_code']});
      detector.detect(canvas).then(function(codes){
        if(codes.length>0) showQRResult(codes[0].rawValue);
        else if(typeof toast==='function') toast('⚠️ No QR code found in image');
      }).catch(function(){ if(typeof toast==='function') toast('❌ Could not scan QR from image'); });
    };
    img.src = URL.createObjectURL(file);
  } else {
    if(typeof toast==='function') toast('ℹ️ QR detection not supported in this browser');
  }
}

function showQRResult(text){
  var res = document.getElementById('qrResult');
  var txt = document.getElementById('qrResultTxt');
  var openBtn = document.getElementById('qrOpenBtn');
  if(res) res.style.display='block';
  if(txt) txt.textContent = text;
  if(openBtn) openBtn.style.display = (text.startsWith('http')||text.startsWith('www')) ? 'flex' : 'none';
  if(typeof toast==='function') toast('✅ QR Code scanned!');
}

function copyQRResult(){
  var txt = document.getElementById('qrResultTxt');
  if(txt&&navigator.clipboard) navigator.clipboard.writeText(txt.textContent);
  if(typeof toast==='function') toast('✅ Copied!');
}

function openQRLink(){
  var txt = document.getElementById('qrResultTxt');
  if(txt) { var url=txt.textContent; if(!url.startsWith('http')) url='https://'+url; window.open(url,'_blank'); }
}
